import{_ as t}from"./chunks/chat-diagnostics.HMJaz4jC.js";import{_ as s,o as a,c as n,ai as o}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Diagnostics de Chat","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/chat-diagnostics.md","filePath":"fr/guide/chat-diagnostics.md"}'),r={name:"fr/guide/chat-diagnostics.md"};function i(l,e,d,c,u,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="diagnostics-de-chat" tabindex="-1">Diagnostics de Chat <a class="header-anchor" href="#diagnostics-de-chat" aria-label="Permalink to &quot;Diagnostics de Chat&quot;">​</a></h1><p>La page Diagnostics de Chat est le cœur de LLMxRay. Elle combine une interface de chat complète avec une analyse approfondie en temps réel de chaque token produit par le modèle.</p><p><strong>Élément de la barre latérale :</strong> Diagnostics de Chat (premier élément) <strong>Route :</strong> <code>/</code></p><p><img src="'+t+'" alt="Interface Diagnostics de Chat"></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page est divisée en deux zones :</p><ul><li><strong>Panneau gauche</strong> -- Liste des sessions affichant toutes les conversations passées avec horodatage, noms de modèles et nombre de tokens.</li><li><strong>Panneau droit</strong> -- Zone de chat active avec saisie de message, sortie en streaming et onglets de détail de session.</li></ul><h2 id="demarrer-une-conversation" tabindex="-1">Démarrer une conversation <a class="header-anchor" href="#demarrer-une-conversation" aria-label="Permalink to &quot;Démarrer une conversation&quot;">​</a></h2><ol><li>Sélectionnez un modèle dans le <strong>menu déroulant des modèles</strong> en haut. Les modèles d&#39;embedding sont automatiquement filtrés -- seuls les modèles capables de chat apparaissent.</li><li>Saisissez votre message dans la zone de texte.</li><li>Appuyez sur <strong>Entrée</strong> ou cliquez sur Envoyer.</li></ol><p>Les tokens arrivent un par un avec une <strong>coloration par confiance</strong> : chaque token est teinté en fonction de la vitesse à laquelle le modèle l&#39;a produit. Tokens rapides = confiance élevée (plus vert). Tokens lents = confiance faible (plus orange/rouge).</p><div class="info custom-block"><p class="custom-block-title">La confiance est une approximation</p><p>Comme le endpoint <code>/api/chat</code> d&#39;Ollama n&#39;expose pas les logprobs des tokens, LLMxRay approxime la confiance à partir de la latence inter-tokens. Cela est clairement indiqué dans l&#39;interface. Pour de vrais logprobs, utilisez la fonctionnalité <a href="./benchmark.html">Benchmark</a>.</p></div><h2 id="fonctionnalites" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h2><h3 id="rendu-markdown" tabindex="-1">Rendu Markdown <a class="header-anchor" href="#rendu-markdown" aria-label="Permalink to &quot;Rendu Markdown&quot;">​</a></h3><p>Les réponses du modèle sont rendues en Markdown enrichi avec coloration syntaxique des blocs de code.</p><h3 id="fichiers-joints" tabindex="-1">Fichiers joints <a class="header-anchor" href="#fichiers-joints" aria-label="Permalink to &quot;Fichiers joints&quot;">​</a></h3><p>Cliquez sur le bouton de pièce jointe pour télécharger des fichiers. Pour les <strong>modèles de vision</strong> (comme LLaVA), vous pouvez coller ou télécharger des images directement -- le modèle les analysera.</p><h3 id="commandes-slash" tabindex="-1">Commandes slash <a class="header-anchor" href="#commandes-slash" aria-label="Permalink to &quot;Commandes slash&quot;">​</a></h3><p>Tapez <code>/</code> dans la zone de saisie pour voir les commandes slash disponibles pour des actions rapides.</p><h3 id="conversation-multi-tours" tabindex="-1">Conversation multi-tours <a class="header-anchor" href="#conversation-multi-tours" aria-label="Permalink to &quot;Conversation multi-tours&quot;">​</a></h3><p>Chaque conversation conserve l&#39;historique complet des messages. Le modèle voit tous les messages précédents comme contexte.</p><h3 id="portes-de-qualite-des-reponses" tabindex="-1">Portes de qualite des reponses <a class="header-anchor" href="#portes-de-qualite-des-reponses" aria-label="Permalink to &quot;Portes de qualite des reponses&quot;">​</a></h3><p>Chaque reponse de l&#39;assistant est automatiquement analysee par cinq detecteurs cote client. Lorsque des problemes sont detectes, de petits badges colores apparaissent sous les metriques de la reponse :</p><table tabindex="0"><thead><tr><th>Detecteur</th><th>Condition</th><th>Severite</th></tr></thead><tbody><tr><td><strong>Repetition</strong></td><td>&gt;50% de 4-grammes repetes</td><td>Echec (rouge)</td></tr><tr><td><strong>Repetition</strong></td><td>&gt;30% de 4-grammes repetes</td><td>Attention (jaune)</td></tr><tr><td><strong>Refus</strong></td><td>Correspond a 8 modeles de refus courants</td><td>Attention</td></tr><tr><td><strong>Charabia</strong></td><td>&gt;40% de caracteres non-ASCII (texte &gt;20 car.)</td><td>Attention</td></tr><tr><td><strong>Vide</strong></td><td>0 mots</td><td>Echec</td></tr><tr><td><strong>Vide</strong></td><td>1-9 mots</td><td>Attention</td></tr><tr><td><strong>Troncature</strong></td><td>Limite de tokens atteinte ou &gt;90% du budget sans fin propre</td><td>Attention</td></tr></tbody></table><p>Un petit point colore apparait egalement dans la ligne de metriques pour un scan rapide. Si tous les controles passent, rien de supplementaire n&#39;est affiche.</p><div class="tip custom-block"><p class="custom-block-title">Toute l&#39;analyse est cote client</p><p>Les controles de qualite s&#39;executent instantanement dans votre navigateur sur le texte de la reponse affichee. Aucun appel API, aucun service externe.</p></div><h2 id="analyse-approfondie-des-sessions" tabindex="-1">Analyse approfondie des sessions <a class="header-anchor" href="#analyse-approfondie-des-sessions" aria-label="Permalink to &quot;Analyse approfondie des sessions&quot;">​</a></h2><p>Cliquez sur une session dans le panneau gauche pour explorer six onglets d&#39;analyse :</p><h3 id="onglet-stream" tabindex="-1">Onglet Stream <a class="header-anchor" href="#onglet-stream" aria-label="Permalink to &quot;Onglet Stream&quot;">​</a></h3><p>Chaque token avec ses données de timing affiché dans une liste déroulante. Au-dessus de la liste de tokens, un <strong>tableau de bord de métriques</strong> affiche :</p><ul><li><strong>TTFT</strong> (Time to First Token) -- Temps mis par le modèle pour commencer à répondre</li><li><strong>Tokens/sec</strong> -- Vitesse de génération</li><li><strong>Total tokens</strong> -- Nombre de tokens (prompt + completion)</li><li><strong>Graphique de latence</strong> -- Chronologie visuelle des délais inter-tokens</li></ul><h3 id="onglet-raisonnement" tabindex="-1">Onglet Raisonnement <a class="header-anchor" href="#onglet-raisonnement" aria-label="Permalink to &quot;Onglet Raisonnement&quot;">​</a></h3><p>Si vous utilisez un modèle de raisonnement comme <strong>DeepSeek-R1</strong>, les blocs <code>&lt;think&gt;</code> sont automatiquement analysés et affichés étape par étape. Chaque étape de raisonnement est catégorisée comme pensée, observation, action, conclusion ou réflexion.</p><h3 id="onglet-introspection" tabindex="-1">Onglet Introspection <a class="header-anchor" href="#onglet-introspection" aria-label="Permalink to &quot;Onglet Introspection&quot;">​</a></h3><p>Visualisations des activations de couches, cartes de chaleur d&#39;attention et architecture du modèle.</p><div class="warning custom-block"><p class="custom-block-title">Données illustratives</p><p>Ces visualisations utilisent des données synthétiques pour montrer à quoi ressemblerait une véritable introspection. Elles sont clairement étiquetées &quot;Illustratif&quot; dans l&#39;interface. L&#39;introspection réelle nécessite un accès aux mécanismes internes du modèle qu&#39;Ollama n&#39;expose pas.</p></div><h3 id="onglet-outils" tabindex="-1">Onglet Outils <a class="header-anchor" href="#onglet-outils" aria-label="Permalink to &quot;Onglet Outils&quot;">​</a></h3><p>Une chronologie de tous les appels d&#39;outils effectués par le modèle pendant la conversation, montrant :</p><ul><li>Nom de l&#39;outil et paramètres</li><li>Résultat de l&#39;exécution</li><li>Durée</li></ul><h3 id="onglet-agent" tabindex="-1">Onglet Agent <a class="header-anchor" href="#onglet-agent" aria-label="Permalink to &quot;Onglet Agent&quot;">​</a></h3><p>Un graphe de flux d&#39;états montrant comment un prompt de type agent a progressé à travers les étapes de planification, d&#39;appels d&#39;outils et de synthèse.</p><h3 id="onglet-prompt" tabindex="-1">Onglet Prompt <a class="header-anchor" href="#onglet-prompt" aria-label="Permalink to &quot;Onglet Prompt&quot;">​</a></h3><p>Une analyse anatomique de votre prompt montrant :</p><ul><li>Les sections identifiées (système, utilisateur, contexte, outils, exemples)</li><li>Le nombre de tokens par section</li><li>L&#39;analyse de la structure globale</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Persistance des sessions</strong> -- Toutes les conversations sont stockées dans IndexedDB et survivent aux actualisations du navigateur.</li><li><strong>Changement de modèle</strong> -- Vous pouvez changer de modèle en cours de session. Le nouveau modèle verra l&#39;historique complet de la conversation.</li><li><strong>Performance</strong> -- Le store de tokens utilise <code>shallowRef</code> pour garantir les performances avec des milliers de tokens.</li></ul>',45)])])}const f=s(r,[["render",i]]);export{g as __pageData,f as default};
